1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      flex-direction: column;
21	      justify-content: center;
22	      align-items: center;
23	      gap: 20px;
24	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
25	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
26	      color: white;
27	      font-size: 14px;
28	      text-align: center;
29	      padding: 20px;
30	    }
31	    .circle-container {
32	      cursor: pointer;
33	      border: none;
34	      background: none;
35	      padding: 0;
36	      position: relative;
37	      will-change: transform;
38	    }
39	    .circle-container:hover,
40	    .circle-container:focus-visible {
41	      transform: scale(1.08);
42	    }
43	    .circle-container:focus {
44	      outline: none;
45	    }
46	    .circle-container:focus-visible {
47	      outline: 3px solid rgba(255, 255, 255, 0.7);
48	      outline-offset: 12px;
49	      border-radius: 50%;
50	    }
51	    svg {
52	      width: min(400px, 80vw);
53	      height: min(400px, 80vw);
54	      display: block;
55	      animation: fadeIn 0.6s ease-out;
56	    }
57	    circle {
58	      fill: #ffffff;
59	      stroke: rgba(255, 255, 255, 0.2);
60	      stroke-width: 2;
61	      animation: pulse 3s ease-in-out infinite;
62	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
63	      transition: fill 0.4s ease, r 0.3s ease, stroke 0.4s ease, filter 0.4s ease;
64	    }
65	    .circle-container:hover circle,
66	    .circle-container:focus-visible circle {
67	      fill: #e8f4f8;
68	      r: 205;
69	      stroke: rgba(255, 255, 255, 0.4);
70	    }
71	    .circle-container.active circle {
72	      fill: #ffd700;
73	      stroke: rgba(255, 215, 0, 0.3);
74	      animation: pulse-active 0.6s ease-in-out;
75	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
76	    }
77	    .circle-container.active:hover circle {
78	      fill: #ffed4e;
79	    }
80	    .color-modes {
81	      --color-pink: #ff6b9d;
82	      --color-teal: #4ecdc4;
83	      --color-mint: #95e1d3;
84	    }
85	    .circle-container.color-mode-1 circle {
86	      fill: var(--color-pink);
87	      stroke: rgba(255, 107, 157, 0.3);
88	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.3));
89	    }
90	    .circle-container.color-mode-1:hover circle,
91	    .circle-container.color-mode-1:focus-visible circle {
92	      stroke: rgba(255, 107, 157, 0.5);
93	    }
94	    .circle-container.color-mode-1.active circle {
95	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.5));
96	    }
97	    .circle-container.color-mode-2 circle {
98	      fill: var(--color-teal);
99	      stroke: rgba(78, 205, 196, 0.3);
100	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.3));
101	    }
102	    .circle-container.color-mode-2:hover circle,
103	    .circle-container.color-mode-2:focus-visible circle {
104	      stroke: rgba(78, 205, 196, 0.5);
105	    }
106	    .circle-container.color-mode-2.active circle {
107	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.5));
108	    }
109	    .circle-container.color-mode-3 circle {
110	      fill: var(--color-mint);
111	      stroke: rgba(149, 225, 211, 0.3);
112	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.3));
113	    }
114	    .circle-container.color-mode-3:hover circle,
115	    .circle-container.color-mode-3:focus-visible circle {
116	      stroke: rgba(149, 225, 211, 0.5);
117	    }
118	    .circle-container.color-mode-3.active circle {
119	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.5));
120	    }
121	    .hint {
122	      font-size: 12px;
123	      opacity: 0.85;
124	      transition: opacity 0.3s ease;
125	      letter-spacing: 0.5px;
126	      max-width: 90%;
127	    }
128	    .circle-container:hover ~ .hint,
129	    .circle-container:focus-visible ~ .hint {
130	      opacity: 1;
131	    }
132	    .mode-indicator {
133	      font-size: 10px;
134	      opacity: 0;
135	      margin-top: 8px;
136	      letter-spacing: 1px;
137	      text-transform: uppercase;
138	      transition: opacity 0.3s ease;
139	      height: 16px;
140	    }
141	    .mode-indicator.visible {
142	      opacity: 0.9;
143	    }
144	    @keyframes pulse {
145	      0%, 100% { r: 200; }
146	      50% { r: 202; }
147	    }
148	    @keyframes pulse-active {
149	      0% { r: 200; }
150	      50% { r: 210; }
151	      100% { r: 200; }
152	    }
153	    @keyframes fadeIn {
154	      from { opacity: 0; transform: scale(0.9); }
155	      to { opacity: 1; transform: scale(1); }
156	    }
157	    @keyframes colorShift {
158	      0% { filter: brightness(1); }
159	      50% { filter: brightness(1.2); }
160	      100% { filter: brightness(1); }
161	    }
162	    .color-shifting circle {
163	      animation: colorShift 0.6s ease-out;
164	    }
165	    @media (max-width: 480px) {
166	      body {
167	        gap: 16px;
168	      }
169	      .hint {
170	        font-size: 11px;
171	      }
172	      .mode-indicator {
173	        font-size: 9px;
174	      }
175	    }
176	    @media (prefers-reduced-motion: reduce) {
177	      * {
178	        animation: none !important;
179	        transition: none !important;
180	      }
181	    }
182	  </style>
183	</head>
184	<body>
185	  <main style="text-align: center;">
186	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle">
187	      <svg viewBox="0 0 400 400" aria-hidden="true">
188	        <circle cx="200" cy="200" r="200"/>
189	      </svg>
190	    </button>
191	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
192	  </main>
193	  <div class="hint" id="hint-text" role="status" aria-live="polite">Click to activate • Double-click to change color</div>
194	
195	  <script>
196	    const STORAGE_KEY = 'circle-state';
197	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
198	    const COLOR_NAMES = ['Default White', 'Pink', 'Teal', 'Mint'];
199	
200	    const circle = document.getElementById('decorative-circle');
201	    const hint = document.getElementById('hint-text');
202	    const modeIndicator = document.getElementById('mode-indicator');
203	
204	    let state = { active: false, colorMode: 0 };
205	
206	    const saveState = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
207	
208	    const loadState = () => {
209	      try {
210	        const saved = localStorage.getItem(STORAGE_KEY);
211	        if (saved) state = JSON.parse(saved);
212	      } catch (e) {
213	        console.warn('Failed to load state');
214	      }
215	      applyState();
216	    };
217	
218	    const applyState = () => {
219	      circle.classList.remove('active', ...COLOR_MODES);
220	      if (state.active) circle.classList.add('active');
221	      if (state.colorMode > 0) circle.classList.add(COLOR_MODES[state.colorMode]);
222	      updateUI();
223	    };
224	
225	    const toggleActive = () => {
226	      state.active = !state.active;
227	      applyState();
228	      saveState();
229	    };
230	
231	    const cycleColor = () => {
232	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
233	      state.active = true;
234	      circle.classList.add('color-shifting');
235	      setTimeout(() => circle.classList.remove('color-shifting'), 600);
236	      applyState();
237	      saveState();
238	    };
239	
240	    const resetState = () => {
241	      state = { active: false, colorMode: 0 };
242	      applyState();
243	      saveState();
244	    };
245	
246	    const updateHint = (onHover = false) => {
247	      const baseText = state.active ? 'Active! • ' : '';
248	      const actionText = state.active ? 'Double-click or press C to cycle color • Press R to reset' : 'Click to activate • Double-click or press C to cycle color • Press R to reset';
249	      hint.textContent = baseText + actionText;
250	    };
251	
252	    const updateModeIndicator = () => {
253	      if (state.active && state.colorMode > 0) {
254	        modeIndicator.textContent = COLOR_NAMES[state.colorMode];
255	        modeIndicator.classList.add('visible');
256	      } else {
257	        modeIndicator.classList.remove('visible');
258	      }
259	    };
260	
261	    const updateUI = () => {
262	      updateHint();
263	      updateModeIndicator();
264	    };
265	
266	    let lastTapTime = 0;
267	    const TAP_DELAY = 300;
268	
269	    circle.addEventListener('click', toggleActive);
270	    circle.addEventListener('dblclick', (e) => {
271	      e.preventDefault();
272	      cycleColor();
273	    });
274	
275	    circle.addEventListener('touchend', (e) => {
276	      const currentTime = new Date().getTime();
277	      const tapLength = currentTime - lastTapTime;
278	      if (tapLength < TAP_DELAY && tapLength > 0) {
279	        e.preventDefault();
280	        cycleColor();
281	      } else {
282	        lastTapTime = currentTime;
283	      }
284	    });
285	
286	    circle.addEventListener('keydown', (e) => {
287	      const key = e.key.toLowerCase();
288	      if (key === ' ' || key === 'enter') {
289	        e.preventDefault();
290	        toggleActive();
291	      } else if (key === 'c') {
292	        e.preventDefault();
293	        cycleColor();
294	      } else if (key === 'r') {
295	        e.preventDefault();
296	        resetState();
297	      }
298	    });
299	
300	    circle.addEventListener('mouseleave', updateHint);
301	
302	    loadState();
303	    circle.focus();
304	  </script>
305	</body>
306	</html>
